import re
from robot.api import logger

COUNTER_NOT_FOUND = "Counter Not Found in file"


class CountersEvaluator(object):
    def __init__(self):
        self.verification_results = []

    def evaluate_counters(self, counters_data):
        for counter in counters_data:
            self.verification_results.append(self.evaluate_one_counter(counter))
        return self.verification_results

    def evaluate_one_counter(self, counter):
        value = counter['value']
        operator, expected_value = self._parse_expectations(counter)
        if isinstance(value, int):
            return self._evaluate_expression(value, operator, expected_value)
        elif isinstance(value, list):
            return self._evaluate_expression_for_list(value, operator, expected_value)
        return False

    def make_verdict(self):
        return all(self.verification_results)

    def _parse_expectations(self, counter):
        expectations = counter['expectations']
        number_or_symbol_regex = re.compile(r'\d+|\D+')
        parsed_expectations = re.findall(number_or_symbol_regex, expectations)
        return self._get_operator_and_expectations(parsed_expectations)

    @staticmethod
    def _get_operator_and_expectations(expectations):
        operators = ['==', '>=', '<=', '!=', '<>', '<', '>', '+']
        expectations_len = len(expectations)
        if expectations_len == 3 and expectations[1] == '-':
            return [expectations.pop(1), [int(i) for i in expectations]]
        elif expectations[0] == '-':
            return [operators[0], int(expectations[1])*(-1)]
        elif expectations_len == 2 and expectations[0].strip(' ') in operators:
            return [expectations[0].strip(' '), int(expectations[1])]
        elif expectations_len == 1:
            return [operators[0], int(expectations[0])]
        else:
            raise ValueError('Wrong or unavailable expectations value')

    @staticmethod
    def _evaluate_expression(counter_value, operator, expectations):

        evaluations = {
            '==': lambda value, expected: value == expected,
            '>=': lambda value, expected: value >= expected,
            '<=': lambda value, expected: value <= expected,
            '!=': lambda value, expected: value != expected,
            '<>': lambda value, expected: value != expected,
            '<': lambda value, expected: value < expected,
            '>': lambda value, expected: value > expected,
            '-': lambda value, expected: expected[0] <= value < expected[1],
        }
        logger.debug("counter_value {}".format(counter_value))
        logger.debug("operator {}".format(operator))
        logger.debug("expectations {}".format(expectations))
        return evaluations[operator](counter_value, expectations)

    @staticmethod
    def _evaluate_expression_for_list(counters_values, operator, expectations, func=any):
        """
        :param func: Function to check values in list: all or any, defaults to any
        :type func: builtin_function_or_method, optional
        """
        # Handle cases where the value contains the sentinel value
        if counters_values == [COUNTER_NOT_FOUND]:
            logger.warn(f"Counter not found in file. Operator '{operator}' cannot be applied.")  # noqa: E999
            return False

        # Handle empty counters_values list
        if not counters_values:
            logger.warn(f"No values found for the counter. Operator '{operator}' cannot be applied.")  # noqa: E999
            return False

        evaluations = {
            '==': lambda values, expected: func([value == expected for value in values]),
            '>=': lambda values, expected: func([value >= expected for value in values]),
            '<=': lambda values, expected: func([value <= expected for value in values]),
            '!=': lambda values, expected: func([value != expected for value in values]),
            '<>': lambda values, expected: func([value != expected for value in values]),
            '<': lambda values, expected: func([value < expected for value in values]),
            '>': lambda values, expected: func([value > expected for value in values]),
            '-': lambda values, expected: func([expected[0] <= value < expected[1] for value in values]),
            '+': lambda values, expected: sum(values) == expected,
        }
        return evaluations[operator](counters_values, expectations)
